def read_text(path):
    with open(path, 'rb') as f:
        data = f.read()
    if data[:2] == b'\x1f\x8b':
        data = gzip.decompress(data)
    return data.decode('utf-8-sig')


def lines_of(path):
    return [l for l in read_text(path).splitlines() if l.strip()]


def files_in(d):
    out = []
    if os.path.isdir(d):
        for root, _, fs in os.walk(d):
            for f in fs:
                out.append(os.path.join(root, f))
    return sorted(out)


def local_to_utc(naive, tz, dst=None):
    """dst: True/False picks the occurrence of a repeated time; None = first."""
    fold = 0
    if dst is not None:
        a = naive.replace(tzinfo=tz, fold=0)
        b = naive.replace(tzinfo=tz, fold=1)
        if a.utcoffset() != b.utcoffset():
            first_is_dst = bool(a.dst())
            fold = 0 if dst == first_is_dst else 1
    return naive.replace(tzinfo=tz, fold=fold).timestamp()


