    return int(dt.timestamp())


def std_offset(tz):
    d = datetime(2026, 1, 1, tzinfo=tz)
    best = None
    for m in (1, 7):
        x = datetime(2026, m, 1, tzinfo=tz)
        if not x.dst():
            best = x.utcoffset()
    return best if best is not None else d.utcoffset()


def norm_dir(s):
    s = str(s).strip().upper()
    return 'IN' if s in ('IN', 'CLOCK_IN', 'K', 'I') else 'OUT'


