    out = []
    hdr = None
    for row in csv.reader(lines_of(path)):
        if 'Badge' in row and 'Punch' in row:
            hdr = {n.strip(): i for i, n in enumerate(row)}
            continue
        if hdr is None:
            continue
        g = lambda k: row[hdr[k]].strip()
        mo, da, yr = g('Date').split('/')
        t = g('Time').upper()
        pm = None
        if t.endswith('AM') or t.endswith('PM'):
            pm = t.endswith('PM')
            t = t[:-2].strip()
        h, mi, s = [int(x) for x in t.split(':')]
        if pm is not None:
            h = h % 12 + (12 if pm else 0)
        naive = datetime(int(yr), int(mo), int(da), h, mi, s)
        z = g('Zone').upper() if 'Zone' in hdr else ''
        dst = True if z.endswith('DT') else (False if z.endswith('ST') else None)
        out.append((g('Record'), g('Badge'), norm_dir(g('Punch')), local_to_utc(naive, tz, dst)))
    return out


