            schema = int(o['schema'])
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2 or 'epoch_ms' in o:
            pid, emp, d = o['punch_id'], o['employee'], o['direction']
            t = int(o['epoch_ms']) // 1000
        else:
            pid, emp, d = o['id'], o['emp'], o['dir']
            t = int(o['ts']) if 'ts' in o else int(o['ts_ms']) // 1000
        out.append((str(pid), emp, norm_dir(d), t))
    return out


def parse_offset(path, tz):
    out = []
    rows = list(csv.reader(lines_of(path), delimiter=';'))
    hdr = None
    for row in rows:
        if 'punch_id' in row:
            hdr = {n: i for i, n in enumerate(row)}
            continue
        g = lambda k: row[hdr[k]]
        out.append((g('punch_id'), g('employee'), norm_dir(g('event')),
                    epoch(datetime.fromisoformat(g('timestamp')))))
    return out


def parse_legacy(path, tz):
