    pend = date.fromisoformat(period['end'])
    cutoff = datetime.fromisoformat(period['corrections_cutoff'].replace('Z', '+00:00')).timestamp()

    sites = {}
    for r in csv.DictReader(read_text(os.path.join(indir, 'sites.csv')).splitlines()):
        sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    employees = {}
    for r in csv.DictReader(read_text(os.path.join(indir, 'employees.csv')).splitlines()):
        employees[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    for r in csv.DictReader(read_text(os.path.join(indir, 'rates.csv')).splitlines()):
        rates.setdefault(r['employee_id'].strip(), []).append(
            (date.fromisoformat(r['effective_from'].strip()), Decimal(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    # 1. collect
    punches = {}  # (site, id) -> [emp, dir, t]
    ever = set()
    for site, (tz, fmt) in sites.items():
        for path in files_in(os.path.join(indir, 'exports', site)):
