            if k in punches:
                del punches[k]
                applied += 1
        elif act == 'set':
            if k in punches:
                punches[k][2] = epoch(datetime.fromisoformat(r['time'].strip()))
                applied += 1
        elif act == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [r['employee'].strip(), norm_dir(r['type']),
