        return datetime.fromtimestamp(t, sites[employees[emp]][0]).date()

    def inperiod(d):
        return pstart <= d <= pend

    nightcache = {}

    def is_night(t, tz, key):
        blk = t // 900
        ck = (key, blk)
        v = nightcache.get(ck)
        if v is None:
            dt = datetime.fromtimestamp(blk * 900, tz)
            mod = dt.hour * 60 + dt.minute
            v = mod >= 1320 or mod < 360
            nightcache[ck] = v
        return v

    def night_minutes(a, b, tz, key):
        n = 0
        t = a
        while t < b:
            if is_night(t, tz, key):
                n += 1
            t += 60
        return n

    for emp, lst in byemp.items():
        lst.sort()
        kept = []
        last = None
        for t, _, site, pid, d in lst:
            if last is not None and last[4] == d and t - last[0] <= 300:
                if inperiod(workday(rnd(t, site), emp)):
                    exc['duplicates_dropped'] += 1
                continue
            last = (t, 0, site, pid, d)
            kept.append((rnd(t, site), site, d))
        shifts = []
        pend = None
        for rt, site, d in kept:
            if d == 'IN':
                if pend:
                    if inperiod(workday(pend[0], emp)):
                        exc['open_shifts'] += 1
                pend = (rt, site)
            else:
                if pend and rt - pend[0] <= 57600:
                    shifts.append((pend[0], rt, pend[1]))
                    pend = None
                else:
                    if pend:
                        if inperiod(workday(pend[0], emp)):
                            exc['open_shifts'] += 1
                        pend = None
                    if inperiod(workday(rt, emp)):
                        exc['orphan_outs'] += 1
        if pend and inperiod(workday(pend[0], emp)):
            exc['open_shifts'] += 1

        rows = []
        for a, b, site in shifts:
            wd = workday(a, emp)
            if not inperiod(wd):
                continue
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(a, b, sites[site][0], site), paid)
            rows.append((a, wd, paid, night))
        rows.sort()
        daily = {}
        weekly = {}
        st = stats[emp]
        total = Decimal(0)
        for a, wd, paid, night in rows:
            dprev = daily.get(wd, 0)
            daily[wd] = dprev + paid
            dot = max(0, dprev + paid - 480) - max(0, dprev - 480)
            nd = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            wprev = weekly.get(wk, 0)
            weekly[wk] = wprev + nd
            wot = max(0, wprev + nd - 2400) - max(0, wprev - 2400)
            ot = dot + wot
            reg = paid - ot
            rl = rates.get(emp, [])
            rate = None
            for ef, r in rl:
                if ef <= wd:
                    rate = r
            if rate is None and rl:
                rate = rl[0][1]
            if rate is None:
                rate = Decimal(0)
            total += rate * (Decimal(reg) + Decimal('1.5') * ot) / 60 + rate * Decimal('0.15') * night / 60
            st['shifts'] += 1
            st['paid'] += paid
            st['ot'] += ot
            st['night'] += night
        st['gross'] = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    res = {'period': {'start': period['start'], 'end': period['end']}, 'employees': {},
           'exceptions': exc, 'totals': {}}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Decimal(0))
    for e in sorted(employees):
        s = stats[e]
        res['employees'][e] = {'shifts': s['shifts'], 'paid_minutes': s['paid'],
                               'overtime_minutes': s['ot'], 'night_minutes': s['night'],
                               'gross': format(s['gross'], '.2f')}
        tot['shifts'] += s['shifts']; tot['paid_minutes'] += s['paid']
        tot['overtime_minutes'] += s['ot']; tot['night_minutes'] += s['night']
        tot['gross'] += s['gross']
    tot['gross'] = format(tot['gross'], '.2f')
    res['totals'] = tot
    with open(outfile, 'w') as f:
        json.dump(res, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
